import{z as n,x as A,o as r,c as d,q as t,j as l,D as E,d as o,s as i,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"MESI","description":"","frontmatter":{"title":"MESI","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mesi-protocol.md","filePath":"cs/mesi-protocol.md","lastUpdated":1791063341000}'),p={name:"cs/mesi-protocol.md"};function C(c,a,m,S,h,M){const s=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=t('<h1 id="mesi" tabindex="-1">MESI <a class="header-anchor" href="#mesi" aria-label="Permalink to &quot;MESI&quot;">​</a></h1><div class="epigraph"><p>一行在每个 cache 里只能处于修改、独占、共享、无效之一；写前先拿到独占，读共享则大家标签相同。</p><footer>—— 据 Papamarcos and Patel, A Low-Overhead Coherence Solution for Multiprocessors with Private Cache Memories, ISCA 1984 整理</footer></div><p><a href="/cs/multicore-shared-cache">上一课</a>让每个核握有私有 L1。<a href="/cs/multicore-shared-cache">一致性问题引入</a>要的不变式还没有状态机。<a href="/cs/write-back-allocate">写回与写分配</a>的脏位是单核的；多核要区分「脏且独有」和「干净可共享」。本课不重讲 LLC 拓扑。缺口是一份可实现的窥探协议：MESI。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只靠「写则广播数据」带宽太大；只靠「写则作废」必须保证写者有最新副本。需要四个状态：Invalid 无有效副本；Shared 干净，他人也可有；Exclusive 干净且独有，可静默变脏；Modified 脏且独有。缺口不是新的 cache 容量，而是<strong>状态转换与总线事务对应</strong>，使得任意时刻至多一份 Modified，且 Shared 时无脏副本。</p><p><span class="marginnote">术语翻译：窥探（snooping）就是每个核的 cache 都「旁听」同一条共享总线——谁发出读或写请求人人看得见，各自据此更新自己那行的状态，像全班竖着耳朵听广播。</span></p><p>Papamarcos–Patel 的 Illinois 协议是 MESI 的经典表述。本课按教学简化，不穷尽每种竞态下的时序图。</p><p><span class="marginnote">MSI 没有 Exclusive：独有的干净行也要写时再占总线。MESI 用 E 省掉那一次。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>窥探：每核看见总线上的读/写请求。读缺失：若他核为 M，先写回再提供数据，双方变 S；若无脏，从 LLC/DRAM 填入，根据「是否独有」进 E 或 S。写缺失或 S 上写：发作废，等他核 I，自己变 M。替换 M 行必须写回。</p>',10)),(r(),l(B,null,{default:E(()=>[i(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22I%20%E6%97%A0%E6%95%88%22%5D%20--%3E%7C%22%E8%AF%BB%E4%B8%94%E7%8B%AC%E6%9C%89%22%7C%20E%5B%22E%20%E7%8B%AC%E5%8D%A0%E5%B9%B2%E5%87%80%22%5D%0A%20%20I%20--%3E%7C%22%E8%AF%BB%E4%B8%94%E4%BB%96%E4%BA%BA%E4%B9%9F%E6%9C%89%22%7C%20S%5B%22S%20%E5%85%B1%E4%BA%AB%E5%B9%B2%E5%87%80%22%5D%0A%20%20E%20--%3E%7C%22%E6%9C%AC%E6%A0%B8%E5%86%99%22%7C%20M%5B%22M%20%E4%BF%AE%E6%94%B9%22%5D%0A%20%20S%20--%3E%7C%22%E6%9C%AC%E6%A0%B8%E5%86%99%E4%BD%9C%E5%BA%9F%E4%BB%96%E4%BA%BA%22%7C%20M%0A%20%20M%20--%3E%7C%22%E4%BB%96%E6%A0%B8%E8%AF%BB%22%7C%20S%0A%20%20E%20--%3E%7C%22%E4%BB%96%E6%A0%B8%E8%AF%BB%22%7C%20S%0A%20%20M%20--%3E%7C%22%E4%BB%96%E6%A0%B8%E5%86%99%22%7C%20I%0A%20%20S%20--%3E%7C%22%E4%BB%96%E6%A0%B8%E5%86%99%22%7C%20I%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"该机保证：读到的值是最近一次已提交写（在一致性意义上的「最近」——全局序由总线仲裁给出）。与 ROB 的配合：只有提交的 store 才发出作废或升级，未提交写留在核内。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：以为 MESI 保证「我的两条 store 按程序顺序被他核看见」。它只管同一地址的副本一致；不同地址之间的可见顺序由存储一致性模型另管，这正是内存屏障存在的理由。")],-1)),a[6]||(a[6]=e("p",null,"假共享：同一行两个字分别被两核写，行在 M 与 I 之间振荡。粒度是行，不是变量。软件对齐可以缓解，协议本身不拆行。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"数字实例：一行通常 64 字节。两个 8 字节计数器挤在同一行时，即使逻辑上毫不相干，两核交替写也会不停互发作废；用对齐把两个变量挪进不同的行，振荡立刻消失。")],-1)),(r(),l(B,null,{default:E(()=>[i(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20W0%5B%22%E6%A0%B80%20%E5%86%99%E5%8F%98%E9%87%8F%20x%22%5D%20--%3E%20M0%5B%22%E8%A1%8C%E5%9C%A8%E6%A0%B80%20%E8%BF%9B%20M%22%5D%0A%20%20W1%5B%22%E6%A0%B81%20%E5%86%99%E5%90%8C%E8%A1%8C%E7%9A%84%20y%22%5D%20--%3E%20INV%5B%22%E4%BD%9C%E5%BA%9F%E8%AF%B7%E6%B1%82%E5%8F%91%E5%88%B0%E6%A0%B80%2C%20%E5%85%B6%E5%89%AF%E6%9C%AC%E5%8F%98%20I%22%5D%0A%20%20M0%20--%3E%20INV%0A%20%20INV%20--%3E%20W2%5B%22%E6%A0%B80%20%E5%86%8D%E5%86%99%20x%3A%20%E5%8F%88%E5%8F%91%E4%BD%9C%E5%BA%9F%E6%8A%A2%E5%9B%9E%22%5D%0A%20%20W2%20--%3E%20OSC%5B%22%E8%A1%8C%E5%9C%A8%20M%20%E4%B8%8E%20I%20%E9%97%B4%E6%8C%AF%E8%8D%A1%2C%20%E5%B8%A6%E5%AE%BD%E7%99%BD%E8%80%97%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MOESI 的 Owned、不引入目录协议。大规模上窥探广播不可扩展，那是互连课的动机之一。也不把 MESI 当成存储模型：它管副本相同，不管两个地址的 store 以何种顺序被他核看见。</p><p>后课默认：私有 cache 行带 MESI 状态；写前求 M，共享读为 S。程序员仍要另问「我的两条 store 他核怎么看见」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MESI 四态维持单地址副本不变式；写前独占。</li><li>Exclusive 避免干净独有行写时占总线。</li><li>多地址上的顺序是下一课存储一致性。</li><li>出处：Papamarcos and Patel, <em>ISCA</em>, 1984；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',5))])}const f=n(p,[["render",C]]);export{I as __pageData,f as default};
